UPDATE dcalendar
SET title = #{title},
    start_date = #{start_date},
    end_date = #{end_date},
    content = #{content}
WHERE dcal_idx = #{dcal_idx}

UPDATE scalendar
SET title = #{title},
    start_date = #{start_date},
    end_date = #{end_date},
    content = #{content}
WHERE scal_idx = #{scal_idx}
